rules.script:
if !active("EN", "en") {
    warn("EN is the active-high enable; tie EN to IN for always-on, or drive it above V_HI (1V) to enable and below V_LO (0.3V) to disable.", ["EN"])
  } else {
    ok()
  }

if active("OUT", "out") {
    warn("OUT is the 3.3V output; a 1uF-or-larger ceramic output capacitor to GND is required for stability (min 0.47uF).
", ["OUT"])
  } else {
    ok()
  }
